//! Worker-side EAGLE-3 draft lane: the draft model plus per-request draft state.
//!
//! Like the DFlash lane it lives on the worker thread next to the target model,
//! because the drafter reads the target's embeddings and the hidden states the
//! target captures at prefill and verify. Those hidden states stay private to
//! this lane; the draft/verify boundary is a pure token span.

use std::collections::HashMap;

use anyhow::Result;
use pegainfer_core::tensor::HiddenStates;

use super::DraftMeta;
use super::LocalQwen3Lane;
use super::PrefillStepItem;
use super::RequestId;
use super::dflash_prefill::prefill_capture_supported;
use crate::eagle3::EAGLE3_CHAIN_LENGTH;
use crate::eagle3::EAGLE3_MAX_BATCH;
use crate::eagle3::Eagle3DraftModel;
use crate::eagle3::Eagle3RequestState;
use crate::eagle3::Eagle3Scratch;
use crate::eagle3::aux_hidden_state_layers;
use crate::speculative::DraftRequestResult;
use crate::speculative::DraftResult;
use crate::speculative::DraftStepItem;
use crate::speculative::VerifyRequestResult;
use crate::speculative::VerifyStepItem;

pub(super) struct Eagle3LaneState {
    model: Eagle3DraftModel,
    requests: HashMap<RequestId, Eagle3RequestState>,
    scratch: Eagle3Scratch,
    /// Target layers whose post-layer hidden states feed the drafter's `fc`.
    aux_layers: [usize; 3],
}

impl Eagle3LaneState {
    pub(super) fn aux_layers(&self) -> &[usize] {
        &self.aux_layers
    }
}

/// Whether a prefill step seeds the drafter for `req`. v1 is greedy only, and
/// `prefill_prompt` needs the whole prompt in one chunk; anything else decodes
/// without speculation.
fn eagle3_prefill_eligible(req: &PrefillStepItem) -> bool {
    prefill_capture_supported(req)
        && req.params.is_greedy()
        && req.chunk_start == 0
        && req.chunk_tokens == req.prompt_tokens.len()
        && req.chunk_tokens >= 2
}

impl LocalQwen3Lane {
    /// Load the EAGLE-3 draft model into this lane (primary rank only).
    pub(super) fn load_eagle3(&mut self, draft_path: &str) -> Result<DraftMeta> {
        let ctx = self.model.device_ctx();
        let model = Eagle3DraftModel::from_safetensors_for_target(ctx, draft_path, &self.model)?;
        let aux_layers = aux_hidden_state_layers(self.model.config().num_hidden_layers)?;
        let scratch = model.new_scratch(ctx)?;
        let meta = DraftMeta {
            block_size: EAGLE3_CHAIN_LENGTH + 1,
            num_spec_tokens: EAGLE3_CHAIN_LENGTH,
            max_position_embeddings: model.config.max_position_embeddings,
            max_draft_batch: Some(EAGLE3_MAX_BATCH),
        };
        self.eagle3 = Some(Eagle3LaneState {
            model,
            requests: HashMap::new(),
            scratch,
            aux_layers,
        });
        Ok(meta)
    }

    pub(super) fn should_capture_eagle3_prefill_context(
        &self,
        requests: &[PrefillStepItem],
    ) -> bool {
        self.eagle3.is_some() && requests.iter().any(eagle3_prefill_eligible)
    }

    /// Seed the drafter from the prompt's captured target hidden states.
    /// Returns the requests that now have draft state.
    pub(super) fn record_prefill_eagle3_context(
        &mut self,
        requests: &[PrefillStepItem],
        capture_requested: bool,
        captured_hidden: Option<&HiddenStates>,
    ) -> Result<Vec<RequestId>> {
        let Some(captured_hidden) = captured_hidden else {
            anyhow::ensure!(
                !capture_requested,
                "EAGLE-3 prefill capture was requested but no hidden states were returned"
            );
            return Ok(Vec::new());
        };
        anyhow::ensure!(
            capture_requested,
            "EAGLE-3 prefill hidden states were returned without a capture request"
        );
        let Some(eagle3) = self.eagle3.as_mut() else {
            anyhow::bail!("EAGLE-3 prefill context record requested without EAGLE-3");
        };
        let expected_tokens: usize = requests.iter().map(|req| req.chunk_tokens).sum();
        anyhow::ensure!(
            captured_hidden.seq_len == expected_tokens,
            "EAGLE-3 prefill captured {} hidden rows for {} scheduled tokens",
            captured_hidden.seq_len,
            expected_tokens
        );
        let ctx = self.model.device_ctx();
        let mut captured_requests = Vec::new();
        let mut token_offset = 0usize;
        for req in requests {
            eagle3.requests.remove(&req.request_id);
            if eagle3_prefill_eligible(req) {
                // Room for every committed token plus one full round past it.
                let max_cache_len =
                    (req.prompt_tokens.len() + req.max_output_tokens + EAGLE3_CHAIN_LENGTH + 1)
                        .min(eagle3.model.config.max_position_embeddings);
                let mut state = eagle3.model.new_request_state(ctx, max_cache_len)?;
                eagle3.model.prefill_prompt(
                    &self.model,
                    &mut state,
                    captured_hidden,
                    token_offset,
                    req.as_slice(),
                )?;
                eagle3.requests.insert(req.request_id, state);
                captured_requests.push(req.request_id);
            }
            token_offset += req.chunk_tokens;
        }
        Ok(captured_requests)
    }

    /// Draft one chain per request: the verify span `[current_token, drafts…]`.
    pub(super) fn execute_eagle3_draft(
        &mut self,
        requests: &[DraftStepItem],
    ) -> Result<DraftResult> {
        let Some(eagle3) = self.eagle3.as_mut() else {
            anyhow::bail!("EAGLE-3 draft requested but EAGLE-3 is not loaded");
        };
        anyhow::ensure!(
            !requests.is_empty() && requests.len() <= EAGLE3_MAX_BATCH,
            "EAGLE-3 drafts 1..={EAGLE3_MAX_BATCH} requests per round, got {}",
            requests.len()
        );
        let Eagle3LaneState {
            model,
            requests: states,
            scratch,
            ..
        } = eagle3;
        let mut outputs = Vec::with_capacity(requests.len());
        for req in requests {
            let state = states
                .get_mut(&req.request_id)
                .ok_or_else(|| anyhow::anyhow!("missing EAGLE-3 state for {:?}", req.request_id))?;
            let drafts = model.chain_round(
                &self.model,
                state,
                scratch,
                req.current_token,
                EAGLE3_CHAIN_LENGTH,
            )?;
            let mut token_ids = Vec::with_capacity(drafts.len() + 1);
            token_ids.push(req.current_token);
            token_ids.extend(drafts);
            outputs.push(DraftRequestResult {
                request_id: req.request_id,
                token_ids,
            });
        }
        Ok(DraftResult { requests: outputs })
    }

    /// Rebuild each request's draft KV over its committed span from the verify
    /// capture, and move its boundary feature to the last committed position.
    pub(super) fn record_verify_eagle3_context(
        &mut self,
        requests: &[VerifyStepItem],
        results: &[VerifyRequestResult],
        captured_hidden: &HiddenStates,
    ) -> Result<()> {
        let Some(eagle3) = self.eagle3.as_mut() else {
            anyhow::bail!("EAGLE-3 verify context record requested without EAGLE-3");
        };
        anyhow::ensure!(
            requests.len() == results.len(),
            "EAGLE-3 verify result count {} does not match request count {}",
            results.len(),
            requests.len()
        );
        let expected_tokens: usize = requests.iter().map(|req| req.token_ids.len()).sum();
        anyhow::ensure!(
            captured_hidden.seq_len == expected_tokens,
            "EAGLE-3 verify captured {} hidden rows for {} scheduled tokens",
            captured_hidden.seq_len,
            expected_tokens
        );
        let mut token_offset = 0usize;
        for (req, result) in requests.iter().zip(results) {
            anyhow::ensure!(
                req.request_id == result.request_id,
                "EAGLE-3 verify result {:?} does not match request {:?}",
                result.request_id,
                req.request_id
            );
            let state = eagle3.requests.get_mut(&req.request_id).ok_or_else(|| {
                anyhow::anyhow!(
                    "missing EAGLE-3 state after verify for {:?}",
                    req.request_id
                )
            })?;
            eagle3.model.rebuild_after_verify(
                &self.model,
                state,
                captured_hidden,
                token_offset,
                &req.token_ids,
                result.matched_draft_tokens,
            )?;
            token_offset += req.token_ids.len();
        }
        Ok(())
    }

    pub(super) fn drop_eagle3_request(&mut self, request_id: RequestId) {
        if let Some(eagle3) = self.eagle3.as_mut() {
            eagle3.requests.remove(&request_id);
        }
    }
}

//! Greedy losslessness check shared by the speculative gates.
//!
//! The verify path runs the prefill attention kernel over the draft span while a
//! plain decode runs the decode kernel, and the two differ by about one bf16
//! ULP, so an exact `spec == baseline` match false-fails on a benign tie flip.
//! At the first divergence the check re-prefills the shared context and accepts
//! the speculative pick only when it sits within `MARGIN_TOL` of that prefill
//! argmax.

// Each integration test crate compiles this module independently and uses a
// different slice of it.
#![allow(dead_code)]

use pegainfer_frontend::sampler::SamplingParams;
use vllm_text::tokenizer::DynTokenizer;

use super::harness::EngineHarness;
use super::harness::Outcome;
use super::harness::request;

/// Top-K logprobs requested from the baseline; wide enough that the speculative
/// pick is in the set on any real tie (a pick outside the top-K is itself a red
/// flag the gate should catch).
pub(crate) const LOGPROBS: usize = 20;
/// Max acceptable regret: how far below the baseline's argmax (in the baseline's
/// own logprobs) the speculative pick may sit at the divergence point. ~3 bf16
/// ULP at typical logit magnitudes — mirrors `hf_golden_gate`'s `MARGIN_TOL`.
pub(crate) const MARGIN_TOL: f32 = 0.20;

/// One decoded position: the chosen token and (when requested) the top-K
/// `(token, logprob)` distribution that produced it.
pub(crate) struct Step {
    pub(crate) id: u32,
    pub(crate) top_logprobs: Vec<(u32, f32)>,
}

/// Fold a finished request's outcome into decoded steps: tokens paired with
/// their requested top-K distributions (empty when logprobs were off).
pub(crate) fn to_steps(outcome: Outcome) -> Vec<Step> {
    let Outcome {
        tokens, logprobs, ..
    } = outcome;
    tokens
        .into_iter()
        .enumerate()
        .map(|(i, id)| Step {
            id,
            top_logprobs: logprobs
                .get(i)
                .and_then(Option::as_ref)
                .map(|lp| lp.top_logprobs.clone())
                .unwrap_or_default(),
        })
        .collect()
}

/// Submit one greedy request and collect the decoded steps until it finishes.
pub(crate) fn generate(
    engine: &EngineHarness,
    prompt_tokens: Vec<u32>,
    logprobs: usize,
    max_tokens: usize,
) -> Vec<Step> {
    let mut req = request(prompt_tokens, SamplingParams::default(), max_tokens);
    req.logprobs = (logprobs > 0).then_some(logprobs);
    to_steps(engine.submit(req).expect_finished())
}

/// Prefill `context` (prompt scoring) and return the next-token distribution the *prefill*
/// kernel produces — the kernel the speculative verify path also uses. This is
/// the reference the spec pick should match (vs the plain-decode baseline, whose
/// kernel resolves bifurcation ties to the other side). Returns the first
/// generated token's `(id, top_logprobs)`.
fn prefill_next(engine: &EngineHarness, context: Vec<u32>, logprobs: usize) -> Step {
    let mut req = request(context, SamplingParams::default(), 1);
    req.logprobs = (logprobs > 0).then_some(logprobs);
    req.prompt_logprobs = Some(logprobs);
    let mut generated = to_steps(engine.submit(req).expect_finished());
    assert!(
        !generated.is_empty(),
        "prompt-scoring prefill finished without a token"
    );
    generated.swap_remove(0)
}

/// Compare one prompt's speculative `spec` steps against its plain-greedy `base`,
/// tolerating only the benign prefill-vs-decode kernel-gap tie flip (the spec
/// pick sits within `MARGIN_TOL` of the prefill kernel's own argmax, measured in
/// the prefill distribution the verify path actually runs). `Ok(())` ⇒ lossless
/// or a benign tie; `Err(diagnostic)` ⇒ a real spec bug. `engine` must be the
/// live speculative engine — at a divergence it re-prefills the shared context
/// (`prompt_tokens` + the matched prefix) to read that prefill-kernel reference.
pub(crate) fn check_lossless(
    engine: &EngineHarness,
    tokenizer: &DynTokenizer,
    i: usize,
    prompt: &str,
    prompt_tokens: &[u32],
    base: &[Step],
    spec: &[Step],
) -> Result<(), String> {
    let matched = base
        .iter()
        .zip(spec)
        .take_while(|(b, s)| b.id == s.id)
        .count();

    // A matching prefix alone does not prove the full continuation was produced.
    if matched == base.len().min(spec.len()) {
        if base.len() != spec.len() {
            return Err(format!(
                "prompt {i}: matching prefix but different output lengths: baseline={}, spec={}",
                base.len(),
                spec.len()
            ));
        }
        eprintln!(
            "prompt {i} ({prompt:?}): {matched}/{} tokens identical (100% lossless)",
            base.len()
        );
        return Ok(());
    }

    let spec_id = spec[matched].id;
    let decode_argmax = base[matched].top_logprobs[0].0;

    // Diagnostic: show the exact branch point.
    {
        let lo = matched.saturating_sub(2);
        let hi = (matched + 3).min(base.len()).min(spec.len());
        let base_ids: Vec<u32> = base[..hi].iter().map(|s| s.id).collect();
        eprintln!("  [diag] prompt {i} matched={matched}");
        eprintln!(
            "  [diag] context+gen base ids {:?} = {:?}",
            base_ids,
            tokenizer.decode(&base_ids, false).unwrap_or_default()
        );
        eprintln!(
            "  [diag] base[{lo}..{hi}] = {:?}",
            base[lo..hi]
                .iter()
                .map(|s| (s.id, tokenizer.decode(&[s.id], false).unwrap_or_default()))
                .collect::<Vec<_>>()
        );
        eprintln!(
            "  [diag] spec[{lo}..{hi}] = {:?}",
            spec[lo..hi]
                .iter()
                .map(|s| (s.id, tokenizer.decode(&[s.id], false).unwrap_or_default()))
                .collect::<Vec<_>>()
        );
    }

    // The verify path runs the prefill kernel, so the right reference for the
    // spec pick is a plain *prefill* of the same shared context — not the
    // plain-decode baseline, whose kernel resolves a bifurcation tie to the
    // other side and amplifies the gap.
    let mut context = prompt_tokens.to_vec();
    context.extend(base[..matched].iter().map(|s| s.id));
    let prefill_ref = prefill_next(engine, context, LOGPROBS);

    if prefill_ref.id == spec_id {
        // Spec faithfully reproduced the prefill-kernel greedy pick; the
        // divergence is purely the pre-existing prefill-vs-decode kernel gap.
        let decode_lp = base[matched]
            .top_logprobs
            .iter()
            .find(|(t, _)| *t == spec_id)
            .map(|(_, lp)| base[matched].top_logprobs[0].1 - lp);
        eprintln!(
            "prompt {i} ({prompt:?}): kernel-gap flip at token {matched} — verify(prefill)→{spec_id}, \
             decode→{decode_argmax}; spec matches prefill greedy (decode-margin {:?}). Not a spec bug.",
            decode_lp
        );
        return Ok(());
    }

    // Spec's greedy pick differs from the prefill-kernel argmax too. The verify
    // path builds its committed KV incrementally across batched speculative
    // spans while this reference prefill builds it in one shot; the two differ by
    // a few bf16 ULP. Within MARGIN_TOL of the prefill argmax ⇒ a benign tie
    // flip; clearly worse ⇒ the verify/accept/capture logic picked a token the
    // forward never favored — a real bug.
    let prefill_regret = prefill_ref
        .top_logprobs
        .iter()
        .find(|(t, _)| *t == spec_id)
        .map(|(_, lp)| prefill_ref.top_logprobs[0].1 - lp);

    if let Some(regret) = prefill_regret {
        if regret <= MARGIN_TOL {
            eprintln!(
                "prompt {i} ({prompt:?}): tie flip at token {matched} — \
                 verify(prefill)→{}, spec→{spec_id}, decode→{decode_argmax}; \
                 spec pick is #2 in the prefill distribution (regret {regret:.3} ≤ {MARGIN_TOL}). \
                 Not a spec bug.",
                prefill_ref.id,
            );
            return Ok(());
        }
    }

    // Either the spec pick is outside the prefill top-K entirely, or it sits
    // clearly below the prefill argmax — neither is a benign tie.
    let decode_regret = base[matched]
        .top_logprobs
        .iter()
        .find(|(t, _)| *t == spec_id)
        .map(|(_, lp)| base[matched].top_logprobs[0].1 - lp);
    Err(format!(
        "prompt {i}: at token {matched} spec chose {spec_id} but prefill greedy says {} and \
         decode greedy says {decode_argmax} (spec regret in prefill dist: {prefill_regret:?} > \
         {MARGIN_TOL}; in decode dist: {decode_regret:?}) — real spec bug",
        prefill_ref.id,
    ))
}

