1	//! Worker-side EAGLE-3 draft lane: the draft model plus per-request draft state.
2	//!
3	//! Like the DFlash lane it lives on the worker thread next to the target model,
4	//! because the drafter reads the target's embeddings and the hidden states the
5	//! target captures at prefill and verify. Those hidden states stay private to
6	//! this lane; the draft/verify boundary is a pure token span.
7	
8	use std::collections::HashMap;
9	
10	use anyhow::Result;
11	use pegainfer_core::tensor::HiddenStates;
12	
13	use super::DraftMeta;
14	use super::LocalQwen3Lane;
15	use super::PrefillStepItem;
16	use super::RequestId;
17	use super::dflash_prefill::prefill_capture_supported;
18	use crate::eagle3::EAGLE3_CHAIN_LENGTH;
19	use crate::eagle3::EAGLE3_MAX_BATCH;
20	use crate::eagle3::Eagle3DraftModel;
21	use crate::eagle3::Eagle3RequestState;
22	use crate::eagle3::Eagle3Scratch;
23	use crate::eagle3::aux_hidden_state_layers;
24	use crate::speculative::DraftRequestResult;
25	use crate::speculative::DraftResult;
26	use crate::speculative::DraftStepItem;
27	use crate::speculative::VerifyRequestResult;
28	use crate::speculative::VerifyStepItem;
29	
30	pub(super) struct Eagle3LaneState {
31	    model: Eagle3DraftModel,
32	    requests: HashMap<RequestId, Eagle3RequestState>,
33	    scratch: Eagle3Scratch,
34	    /// Target layers whose post-layer hidden states feed the drafter's `fc`.
35	    aux_layers: [usize; 3],
36	}
37	
38	impl Eagle3LaneState {
39	    pub(super) fn aux_layers(&self) -> &[usize] {
40	        &self.aux_layers
41	    }
42	}
43	
44	/// Whether a prefill step seeds the drafter for `req`. v1 is greedy only, and
45	/// `prefill_prompt` needs the whole prompt in one chunk; anything else decodes
46	/// without speculation.
47	fn eagle3_prefill_eligible(req: &PrefillStepItem) -> bool {
48	    prefill_capture_supported(req)
49	        && req.params.is_greedy()
50	        && req.chunk_start == 0
51	        && req.chunk_tokens == req.prompt_tokens.len()
52	        && req.chunk_tokens >= 2
53	}
54	
55	impl LocalQwen3Lane {
56	    /// Load the EAGLE-3 draft model into this lane (primary rank only).
57	    pub(super) fn load_eagle3(&mut self, draft_path: &str) -> Result<DraftMeta> {
58	        let ctx = self.model.device_ctx();
59	        let model = Eagle3DraftModel::from_safetensors_for_target(ctx, draft_path, &self.model)?;
60	        let aux_layers = aux_hidden_state_layers(self.model.config().num_hidden_layers)?;
61	        let scratch = model.new_scratch(ctx)?;
62	        let meta = DraftMeta {
63	            block_size: EAGLE3_CHAIN_LENGTH + 1,
64	            num_spec_tokens: EAGLE3_CHAIN_LENGTH,
65	            max_position_embeddings: model.config.max_position_embeddings,
66	            max_draft_batch: Some(EAGLE3_MAX_BATCH),
67	        };
68	        self.eagle3 = Some(Eagle3LaneState {
69	            model,
70	            requests: HashMap::new(),
71	            scratch,
72	            aux_layers,
73	        });
74	        Ok(meta)
75	    }
76	
77	    pub(super) fn should_capture_eagle3_prefill_context(
78	        &self,
79	        requests: &[PrefillStepItem],
80	    ) -> bool {
81	        self.eagle3.is_some() && requests.iter().any(eagle3_prefill_eligible)
82	    }
83	
84	    /// Seed the drafter from the prompt's captured target hidden states.
85	    /// Returns the requests that now have draft state.
86	    pub(super) fn record_prefill_eagle3_context(
87	        &mut self,
88	        requests: &[PrefillStepItem],
89	        capture_requested: bool,
90	        captured_hidden: Option<&HiddenStates>,
91	    ) -> Result<Vec<RequestId>> {
92	        let Some(captured_hidden) = captured_hidden else {
93	            anyhow::ensure!(
94	                !capture_requested,
95	                "EAGLE-3 prefill capture was requested but no hidden states were returned"
96	            );
97	            return Ok(Vec::new());
98	        };
99	        anyhow::ensure!(
100	            capture_requested,
101	            "EAGLE-3 prefill hidden states were returned without a capture request"
102	        );
103	        let Some(eagle3) = self.eagle3.as_mut() else {
104	            anyhow::bail!("EAGLE-3 prefill context record requested without EAGLE-3");
105	        };
106	        let expected_tokens: usize = requests.iter().map(|req| req.chunk_tokens).sum();
107	        anyhow::ensure!(
108	            captured_hidden.seq_len == expected_tokens,
109	            "EAGLE-3 prefill captured {} hidden rows for {} scheduled tokens",
110	            captured_hidden.seq_len,
111	            expected_tokens
112	        );
113	        let ctx = self.model.device_ctx();
114	        let mut captured_requests = Vec::new();
115	        let mut token_offset = 0usize;
116	        for req in requests {
117	            eagle3.requests.remove(&req.request_id);
118	            if eagle3_prefill_eligible(req) {
119	                // Room for every committed token plus one full round past it.
120	                let max_cache_len =
121	                    (req.prompt_tokens.len() + req.max_output_tokens + EAGLE3_CHAIN_LENGTH + 1)
122	                        .min(eagle3.model.config.max_position_embeddings);
123	                let mut state = eagle3.model.new_request_state(ctx, max_cache_len)?;
124	                eagle3.model.prefill_prompt(
125	                    &self.model,
126	                    &mut state,
127	                    captured_hidden,
128	                    token_offset,
129	                    req.as_slice(),
130	                )?;
131	                eagle3.requests.insert(req.request_id, state);
132	                captured_requests.push(req.request_id);
133	            }
134	            token_offset += req.chunk_tokens;
135	        }
136	        Ok(captured_requests)
137	    }
138	
139	    /// Draft one chain per request: the verify span `[current_token, drafts…]`.
140	    pub(super) fn execute_eagle3_draft(
141	        &mut self,
142	        requests: &[DraftStepItem],
143	    ) -> Result<DraftResult> {
144	        let Some(eagle3) = self.eagle3.as_mut() else {
145	            anyhow::bail!("EAGLE-3 draft requested but EAGLE-3 is not loaded");
146	        };
147	        anyhow::ensure!(
148	            !requests.is_empty() && requests.len() <= EAGLE3_MAX_BATCH,
149	            "EAGLE-3 drafts 1..={EAGLE3_MAX_BATCH} requests per round, got {}",
150	            requests.len()
151	        );
152	        let Eagle3LaneState {
153	            model,
154	            requests: states,
155	            scratch,
156	            ..
157	        } = eagle3;
158	        let mut outputs = Vec::with_capacity(requests.len());
159	        for req in requests {
160	            let state = states
161	                .get_mut(&req.request_id)
162	                .ok_or_else(|| anyhow::anyhow!("missing EAGLE-3 state for {:?}", req.request_id))?;
163	            let drafts = model.chain_round(
164	                &self.model,
165	                state,
166	                scratch,
167	                req.current_token,
168	                EAGLE3_CHAIN_LENGTH,
169	            )?;
170	            let mut token_ids = Vec::with_capacity(drafts.len() + 1);
171	            token_ids.push(req.current_token);
172	            token_ids.extend(drafts);
173	            outputs.push(DraftRequestResult {
174	                request_id: req.request_id,
175	                token_ids,
176	            });
177	        }
178	        Ok(DraftResult { requests: outputs })
179	    }
180	
181	    /// Rebuild each request's draft KV over its committed span from the verify
182	    /// capture, and move its boundary feature to the last committed position.
183	    pub(super) fn record_verify_eagle3_context(
184	        &mut self,
185	        requests: &[VerifyStepItem],
186	        results: &[VerifyRequestResult],
187	        captured_hidden: &HiddenStates,
188	    ) -> Result<()> {
189	        let Some(eagle3) = self.eagle3.as_mut() else {
190	            anyhow::bail!("EAGLE-3 verify context record requested without EAGLE-3");
191	        };
192	        anyhow::ensure!(
193	            requests.len() == results.len(),
194	            "EAGLE-3 verify result count {} does not match request count {}",
195	            results.len(),
196	            requests.len()
197	        );
198	        let expected_tokens: usize = requests.iter().map(|req| req.token_ids.len()).sum();
199	        anyhow::ensure!(
200	            captured_hidden.seq_len == expected_tokens,
201	            "EAGLE-3 verify captured {} hidden rows for {} scheduled tokens",
202	            captured_hidden.seq_len,
203	            expected_tokens
204	        );
205	        let mut token_offset = 0usize;
206	        for (req, result) in requests.iter().zip(results) {
207	            anyhow::ensure!(
208	                req.request_id == result.request_id,
209	                "EAGLE-3 verify result {:?} does not match request {:?}",
210	                result.request_id,
211	                req.request_id
212	            );
213	            let state = eagle3.requests.get_mut(&req.request_id).ok_or_else(|| {
214	                anyhow::anyhow!(
215	                    "missing EAGLE-3 state after verify for {:?}",
216	                    req.request_id
217	                )
218	            })?;
219	            eagle3.model.rebuild_after_verify(
220	                &self.model,
221	                state,
222	                captured_hidden,
223	                token_offset,
224	                &req.token_ids,
225	                result.matched_draft_tokens,
226	            )?;
227	            token_offset += req.token_ids.len();
228	        }
229	        Ok(())
230	    }
231	
232	    pub(super) fn drop_eagle3_request(&mut self, request_id: RequestId) {
233	        if let Some(eagle3) = self.eagle3.as_mut() {
234	            eagle3.requests.remove(&request_id);
235	        }
236	    }
237	}
