18	use std::path::PathBuf;
19	use std::time::Duration;
20	use std::time::Instant;
21	
22	use pegainfer_frontend::engine::SpecDecodeCounters;
23	use pegainfer_frontend::sampler::SamplingParams;
24	use pegainfer_qwen3::DEFAULT_KV_CACHE_MEMORY_MARGIN_BYTES;
25	use pegainfer_qwen3::DEFAULT_KV_PAGE_SIZE;
26	use pegainfer_qwen3::DEFAULT_MAX_PREFILL_TOKENS;
27	use pegainfer_qwen3::DecodeOverlap;
28	use pegainfer_qwen3::Qwen3LaunchOptions;
29	use pegainfer_qwen3::Qwen3MemoryOptions;
30	use pegainfer_qwen3::Qwen3OffloadOptions;
31	
32	mod common;
33	
34	use common::harness::EngineHarness;
35	use common::harness::RequestStream;
36	use common::harness::request;
37	use common::lossless::LOGPROBS;
38	use common::lossless::Step;
39	use common::lossless::check_lossless;
40	use common::lossless::generate;
41	use common::lossless::to_steps;
42	
43	const MODEL_PATH: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../models/Qwen3-4B");
44	const DRAFT_PATH: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../models/Qwen3-4B_eagle3");
45	const GENERATED_TOKENS: usize = 64;
46	/// The abort test's victim ignores EOS and gets a budget of thousands of tokens
47	/// so that it is meant to still be decoding when the abort is sent. Going idle
48	/// afterwards does not say which path retired it.
49	const VICTIM_TOKENS: usize = 8192;
50	/// How long the abort test waits for the engine to go idle after the abort.
51	const RETIRE_TIMEOUT: Duration = Duration::from_secs(2);
52	
53	const PROMPTS: [&str; 5] = [
54	    "The capital of France is",
55	    "Here is a short story about a dragon. Once upon a time",
56	    "def fibonacci(n):",
57	    "Q: What is 17 multiplied by 23? A: Let's think step by step.",
58	    "The three primary colors are",
59	];
