61	/// One Qwen3-4B engine at a time fits the card; cargo runs tests concurrently.
62	static GPU: std::sync::Mutex<()> = std::sync::Mutex::new(());
63	
64	fn path_or_skip(env: &str, default: &str) -> Option<String> {
65	    match std::env::var(env) {
66	        Ok(path) => Some(path),
67	        Err(_) if Path::new(default).join("config.json").exists() => Some(default.to_string()),
68	        Err(_) => {
69	            eprintln!("skipping eagle3 gate: {default}/config.json missing; set {env}");
70	            None
71	        }
72	    }
73	}
