75	fn paths_or_skip() -> Option<(String, String)> {
76	    Some((
77	        path_or_skip("PEGAINFER_TEST_MODEL_PATH", MODEL_PATH)?,
78	        path_or_skip("PEGAINFER_EAGLE3_TEST_MODEL_PATH", DRAFT_PATH)?,
79	    ))
80	}
