82	fn launch(model_path: &str, draft: Option<&str>) -> EngineHarness {
83	    let options = Qwen3LaunchOptions {
84	        device_ordinal: 0,
85	        tp_size: 1,
86	        cuda_graph: true,
87	        dump_graph_png: None,
88	        offload: Qwen3OffloadOptions::disabled(),
89	        // The speculative engine forces the prefix cache off; match it on the
90	        // baseline so both take the same cold prefill path.
91	        no_prefix_cache: true,
92	        max_prefill_tokens: DEFAULT_MAX_PREFILL_TOKENS,
93	        memory: Qwen3MemoryOptions::new(
94	            0.85,
95	            DEFAULT_KV_CACHE_MEMORY_MARGIN_BYTES,
96	            DEFAULT_KV_PAGE_SIZE,
97	        )
98	        .validate()
99	        .expect("valid memory options"),
100	        lora: None,
101	        decode_overlap: DecodeOverlap::Off,
102	        batch_invariant: false,
103	        dflash_draft_model_path: None,
104	        eagle3_draft_model_path: draft.map(PathBuf::from),
105	    };
106	    EngineHarness::new(
107	        pegainfer_qwen3::launch(Path::new(model_path), options).expect("failed to start engine"),
108	    )
109	}
