111	/// Plain greedy decode (speculation off) with logprobs, one prompt at a time.
112	/// Each case is `(prompt_tokens, max_tokens)`.
113	fn baseline(model_path: &str, cases: &[(Vec<u32>, usize)]) -> Vec<Vec<Step>> {
114	    let engine = launch(model_path, None);
115	    let out = cases
116	        .iter()
117	        .map(|(tokens, max_tokens)| generate(&engine, tokens.clone(), LOGPROBS, *max_tokens))
118	        .collect();
119	    drop(engine);
120	    out
121	}
122	
123	fn counters(engine: &EngineHarness) -> SpecDecodeCounters {
124	    engine
125	        .metrics()
126	        .spec_decode
127	        .expect("EAGLE-3 engine publishes speculative counters")
128	}
129	
130	/// Counters read right after launch, when the scheduler may not have published
131	/// its first snapshot yet; before any step every count is zero.
132	fn launch_counters(engine: &EngineHarness) -> SpecDecodeCounters {
133	    engine.metrics().spec_decode.unwrap_or_default()
134	}
135	
136	/// Drafts proposed and accepted since `before`, with the accepted count per
137	/// draft position (the accepted-length distribution).
138	fn report(name: &str, before: &SpecDecodeCounters, after: &SpecDecodeCounters) -> (u64, u64) {
139	    let proposed = after.num_draft_tokens - before.num_draft_tokens;
140	    let accepted = after.num_accepted_tokens - before.num_accepted_tokens;
141	    let width = usize::try_from(after.num_spec_tokens).expect("spec width fits usize");
142	    let per_pos: Vec<u64> = (0..width)
143	        .map(|i| after.num_accepted_tokens_per_pos[i] - before.num_accepted_tokens_per_pos[i])
144	        .collect();
145	    eprintln!(
146	        "eagle3 {name}: rounds={}, proposed={proposed}, accepted={accepted}, per_position={per_pos:?}",
147	        after.num_drafts - before.num_drafts
148	    );
149	    (proposed, accepted)
150	}
151	
152	/// Read updates from `stream` until it has produced at least `tokens` tokens,
153	/// and return them.
154	fn take_tokens(stream: &mut RequestStream, tokens: usize) -> Vec<Step> {
155	    let mut steps = Vec::new();
156	    while steps.len() < tokens {
157	        let update = stream.recv().expect("engine closed the stream");
158	        assert!(
159	            update.terminal.is_none(),
160	            "request finished after {} tokens",
161	            steps.len()
162	        );
163	        steps.extend(update.tokens.iter().map(|&id| Step {
164	            id,
165	            top_logprobs: Vec::new(),
166	        }));
167	    }
168	    steps
169	}
