171	fn encode(model_path: &str, prompts: &[&str]) -> Vec<Vec<u32>> {
172	    let tokenizer = common::load_tokenizer(model_path);
173	    prompts
174	        .iter()
175	        .map(|p| tokenizer.encode(p, false).expect("encode failed"))
176	        .collect()
177	}
