179	#[test]
180	fn eagle3_greedy_matches_plain_greedy() {
181	    common::harness::init_capture_logging();
182	    let Some((model_path, draft_path)) = paths_or_skip() else {
183	        return;
184	    };
185	    let _gpu = GPU
186	        .lock()
187	        .unwrap_or_else(std::sync::PoisonError::into_inner);
188	    let tokenizer = common::load_tokenizer(&model_path);
189	    let encoded = encode(&model_path, &PROMPTS);
190	    let cases: Vec<_> = encoded
191	        .iter()
192	        .map(|t| (t.clone(), GENERATED_TOKENS))
193	        .collect();
194	    let base = baseline(&model_path, &cases);
195	
196	    let engine = launch(&model_path, Some(&draft_path));
197	    let before = launch_counters(&engine);
198	    let specs: Vec<Vec<Step>> = encoded
199	        .iter()
200	        .map(|t| generate(&engine, t.clone(), 0, GENERATED_TOKENS))
201	        .collect();
202	    let (proposed, accepted) = report("greedy", &before, &counters(&engine));
203	    assert!(
204	        proposed > 0 && accepted > 0,
205	        "EAGLE-3 never drafted or never had a draft accepted"
206	    );
207	    let failures: Vec<String> = PROMPTS
208	        .iter()
209	        .enumerate()
210	        .filter_map(|(i, prompt)| {
211	            check_lossless(
212	                &engine,
213	                &tokenizer,
214	                i,
215	                prompt,
216	                &encoded[i],
217	                &base[i],
218	                &specs[i],
219	            )
220	            .err()
221	        })
222	        .collect();
223	    assert!(
224	        failures.is_empty(),
225	        "EAGLE-3 greedy decode is not lossless:\n{}",
226	        failures.join("\n")
227	    );
228	}
