230	/// The scheduler clamps each verify span to the request's remaining output
231	/// budget, so short budgets end a request on spans of every length from one
232	/// token up to the full chain, and the draft rebuild runs on each.
233	#[test]
234	fn eagle3_output_budget_edges_match_plain_greedy() {
235	    let Some((model_path, draft_path)) = paths_or_skip() else {
236	        return;
237	    };
238	    let _gpu = GPU
239	        .lock()
240	        .unwrap_or_else(std::sync::PoisonError::into_inner);
241	    let tokenizer = common::load_tokenizer(&model_path);
242	    let prompt = PROMPTS[1];
243	    let tokens = encode(&model_path, &[prompt]).remove(0);
244	    let budgets = [1usize, 2, 3, 4, 5, 6, 9];
245	    let cases: Vec<_> = budgets.iter().map(|&b| (tokens.clone(), b)).collect();
246	    let base = baseline(&model_path, &cases);
247	
248	    let engine = launch(&model_path, Some(&draft_path));
249	    let before = launch_counters(&engine);
250	    let specs: Vec<Vec<Step>> = budgets
251	        .iter()
252	        .map(|&b| generate(&engine, tokens.clone(), 0, b))
253	        .collect();
254	    let (proposed, _) = report("budget edges", &before, &counters(&engine));
255	    assert!(proposed > 0, "EAGLE-3 never drafted");
256	    for (i, (base, spec)) in base.iter().zip(&specs).enumerate() {
257	        check_lossless(&engine, &tokenizer, i, prompt, &tokens, base, spec)
258	            .unwrap_or_else(|failure| panic!("budget {}: {failure}", budgets[i]));
259	    }
