262	/// After a drafting request is aborted the engine goes idle, and the next
263	/// request drafts and stays lossless.
264	#[test]
265	fn eagle3_abort_mid_speculation_keeps_the_engine_lossless() {
266	    let Some((model_path, draft_path)) = paths_or_skip() else {
267	        return;
268	    };
269	    let _gpu = GPU
270	        .lock()
271	        .unwrap_or_else(std::sync::PoisonError::into_inner);
272	    let tokenizer = common::load_tokenizer(&model_path);
273	    let encoded = encode(&model_path, &PROMPTS[..2]);
274	    let base = baseline(&model_path, &[(encoded[1].clone(), GENERATED_TOKENS)]);
275	
276	    let engine = launch(&model_path, Some(&draft_path));
277	    let start = launch_counters(&engine);
278	    let victim_params = SamplingParams {
279	        ignore_eos: true,
280	        ..SamplingParams::default()
281	    };
282	    let mut victim = engine.submit(request(encoded[0].clone(), victim_params, VICTIM_TOKENS));
283	    take_tokens(&mut victim, 16);
284	    let (proposed, _) = report("victim", &start, &counters(&engine));
285	    assert!(proposed > 0, "the victim never drafted before the abort");
286	    victim.control.abort();
287	    drop(victim);
288	    let deadline = Instant::now() + RETIRE_TIMEOUT;
289	    while engine.metrics().num_running_reqs > 0 {
290	        assert!(
